const items = $input.all();
const week = new Date().toISOString().substring(0,7);
const thisWeek = items.filter(i => i.json.week === week && i.json.status !== 'archived');
return [{ json: { findings: thisWeek.map(i=>i.json), count: thisWeek.length, week } }];

const items = $input.all();
const cutoff = new Date(Date.now() - 7*24*60*60*1000).toISOString();
const recent = items.filter(i => i.json.timestamp >= cutoff);
return [{ json: { errors: recent.map(i=>i.json), error_count: recent.length } }];

const all = $input.all();
const findingsItem = all.find(i => i.json.findings !== undefined) || { json: { findings: [], count: 0, week: new Date().toISOString().substring(0,7) } };
const errorsItem = all.find(i => i.json.errors !== undefined) || { json: { errors: [], error_count: 0 } };
return [{ json: { findings: findingsItem.json.findings, findings_count: findingsItem.json.count, week: findingsItem.json.week, errors: errorsItem.json.errors, error_count: errorsItem.json.error_count } }];

const apiResp = $input.first().json;
const data = $('Prepare Newsletter Prompt').first().json;
const newsletter = apiResp.content?.[0]?.text || 'Error: no content in API response';
const { prompt, ...rest } = data;
return [{ json: { ...rest, newsletter_content: newsletter, generated_at: new Date().toISOString() } }];

const data = $input.first().json;
const content = data.newsletter_content || '';

function parseMarkdown(text) {
  const lines = text.split('\n');
  let html = '';
  let inList = false;

  for (const line of lines) {
    if (inList && !line.startsWith('- ')) {
      html += '</ul>';
      inList = false;
    }

    if (line.startsWith('## ')) {
      const title = line.substring(3).trim();
      html += `<h2 style="color:#1a2744;font-size:13px;font-weight:700;text-transform:uppercase;letter-spacing:0.08em;border-left:4px solid #e85d04;padding-left:12px;margin:28px 0 10px 0;">${title}</h2>`;
    } else if (line.trim() === '---') {
      html += '<hr style="border:none;border-top:1px solid #e5e7eb;margin:24px 0;">';
    } else if (line.startsWith('- ')) {
      if (!inList) {
        html += '<ul style="margin:8px 0 8px 0;padding-left:18px;">';
        inList = true;
      }
      const itemText = line.substring(2).replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');
      html += `<li style="margin:6px 0;color:#374151;font-size:14px;line-height:1.65;">${itemText}</li>`;
    } else if (line.trim() === '') {
      // skip blank lines
    } else {
      const paraText = line.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');
      html += `<p style="color:#374151;font-size:14px;line-height:1.7;margin:8px 0;">${paraText}</p>`;
    }
  }

  if (inList) html += '</ul>';
  return html;
}

const bodyHtml = parseMarkdown(content);

const formattedDate = new Date(data.generated_at).toLocaleDateString('en-US', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
});

const [weekYear, weekMonth] = data.week.split('-');
const formattedWeek = new Date(parseInt(weekYear), parseInt(weekMonth) - 1).toLocaleString('en-US', { month: 'long' }) + ' ' + weekYear;

const newsletter_html = `<!DOCTYPE html>\n<html>\n<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width,initial-scale=1.0">\n</head>\n<body style="margin:0;padding:0;background-color:#f0f2f5;font-family:Arial,Helvetica,sans-serif;">\n  <div style="max-width:600px;margin:32px auto;background:#ffffff;border-radius:8px;overflow:hidden;box-shadow:0 2px 12px rgba(0,0,0,0.10);">\n\n    <div style="background:#1a2744;padding:28px 32px;">\n      <div style="color:#e85d04;font-size:10px;font-weight:700;letter-spacing:0.12em;text-transform:uppercase;margin-bottom:6px;">PING IDENTITY</div>\n      <div style="color:#ffffff;font-size:20px;font-weight:700;margin:0;">Product Intelligence</div>\n      <div style="color:#94a3b8;font-size:13px;margin-top:4px;">Weekly Intel &mdash; ${formattedWeek}</div>\n    </div>\n\n    <div style="padding:28px 32px 20px 32px;">\n      ${bodyHtml}\n    </div>\n\n    <div style="background:#f8fafc;padding:16px 32px;border-top:1px solid #e5e7eb;">\n      <p style="color:#9ca3af;font-size:11px;margin:0;text-align:center;">\n        Generated by Product Intelligence OS &middot; ${formattedDate}\n      </p>\n    </div>\n\n  </div>\n</body>\n</html>`;

return [{ json: { ...data, newsletter_html, week_label: formattedWeek } }];
